; z80nflg2.asm: generated by build_flags2.py (Strobe Fern, Fri 6 Nov 2026). See its docstring.
PREG    EQU 0x243B

        org 0x8000
start:  di
        ld (bas_sp),sp
        ld sp,0xBD00
        ld a,0x01
        call nr_read
        ld (sv01),a
        ld a,0x0E
        call nr_read
        ld (sv0e),a
        ld a,0x7F
        call nr_read
        ld (sv7f),a
        call cell0
        call cell1
        call cell2
        call cell3
        call cell4
        ld a,(0x5C48)           ; the border back from BORDCR
        rrca
        rrca
        rrca
        and 7
        out (0xFE),a
        ld a,(sv7f)             ; put user register 0 back, and select it as Z80NTIME leaves it
        ld e,a
        ld a,0x7F
        call nr_write
        call report
        call photobeep          ; the photo beep (../beep.inc), so find_photos.py can label the frame
        call waitkey
        ld sp,(bas_sp)
        ei
        ret

nr_write:                       ; nextreg A = E
        ld bc,PREG
        out (c),a
        inc b
        out (c),e
        ret

nr_read:
        ld bc,PREG
        out (c),a
        inc b
        in a,(c)
        ret

waitkey:
        xor a
        in a,(0xFE)
        cpl
        and 0x1F
        jr nz,waitkey
wk1:    xor a
        in a,(0xFE)
        cpl
        and 0x1F
        jr z,wk1
        ret

cell0:  ld hl,48112
        ld (hl),0x07
        ld bc,0x00FE            ; B-1 = FFh: out to FFFEh, the ULA (border 7)
        ld de,0x00FF
        push de
        pop af
        db 0xED,0xA3            ; OUTI
        push af
        pop hl
        ld a,l
        ld (fres+0),a
        ret
cell1:  ld hl,48096
        ld (hl),0x07
        ld bc,0x80FE            ; B-1 = 7Fh: out to 7FFEh, the ULA (border 7)
        ld de,0x00FF
        push de
        pop af
        db 0xED,0xA3            ; OUTI
        push af
        pop hl
        ld a,l
        ld (fres+1),a
        ret
cell2:  ld a,i
        ld (savi),a
        xor a
        ld i,a
        ld de,0x00FF
        push de
        pop af
        ld a,i
        push af
        ld a,(savi)
        ld i,a
        pop af
        push af
        pop hl
        ld a,l
        ld (fres+2),a
        ret
cell3:  xor a
        ld r,a                  ; R is 02h-07h by the read: bits 3, 5, 7 clear, not zero
        ld de,0x00FF
        push de
        pop af
        ld a,r
        push af
        pop hl
        ld a,l
        ld (fres+3),a
        ret
cell4:  ld a,0x7F
        ld e,0x00
        call nr_write           ; the port's byte: 00h
        ld bc,0x253B
        ld de,0x00FF
        push de
        pop af
        in a,(c)
        push af
        pop hl
        ld a,l
        ld (fres+4),a
        ret

cls:    call 0x0DAF
        ld a,2
        call 0x1601
        ld a,255
        ld (0x5C8C),a
        ret

putc:   push bc
        push de
        push hl
        rst 0x10
        pop hl
        pop de
        pop bc
        ret

pstr:   ld a,(hl)
        or a
        ret z
        call putc
        inc hl
        jr pstr

phex2:  push af
        rrca
        rrca
        rrca
        rrca
        call phex1
        pop af
phex1:  and 15
        add a,0x90
        daa
        adc a,0x40
        daa
        jp putc

pdec2z: ld b,'0'-1
pz1:    inc b
        sub 10
        jr nc,pz1
        add a,10+'0'
        push af
        ld a,b
        call putc
        pop af
        jp putc

report: call cls
        ld hl,s_t1
        call pstr
        ld a,(sv01)
        rrca
        rrca
        rrca
        rrca
        and 15
        add a,'0'
        call putc
        ld a,'.'
        call putc
        ld a,(sv01)
        and 15
        call pdec2z
        ld a,'.'
        call putc
        ld a,(sv0e)
        call pdec2z
        ld hl,s_t2
        call pstr
        ld ix,tab               ; label (8), then F: got, the T80N's, a Zilog's
        ld de,fres
        ld b,5
rp1:    push bc
        push ix
        pop hl
        call pstr
        inc hl
        push hl
        ld a,' '
        call putc
        ld a,(de)
        call phex2
        inc de
        ld hl,s_sep
        call pstr
        pop hl
        ld a,(hl)
        call phex2
        inc hl
        push hl
        ld hl,s_sep
        call pstr
        pop hl
        ld a,(hl)
        call phex2
        inc hl
        push hl
        pop ix
        ld a,13
        call putc
        pop bc
        djnz rp1
        ld hl,s_leg
        jp pstr

s_t1:   db "Z80NFLG2 (Strobe) core ",0
s_t2:   db 13,"F from FF: got / T80N / Zilog",13,13,0
s_sep:  db " / ",0
s_leg:  db 13,"T80N: the Next's CPU as its VHDL",13
        db "Zilog: and omse-ai today",13,13
        db "photo, then press a key",0
tab:
        db "OUTI B00",0,187,172
        db "OUTI B80",0,62,40
        db "LD A,I  ",0,105,65
        db "LD A,R  ",0,41,1
        db "IN A,(C)",0,109,69
sv01:   db 0
sv0e:   db 0
sv7f:   db 0
savi:   db 0
bas_sp: dw 0
fres:   ds 5
TAPEID  equ 65                ; the photo beep's tape ID (../NOTES.md, "The photo beep")
        include "../beep.inc"
